int function ( int i , ByteBuffer bb , StringBuilder sb ) {
    while ( bb.hasRemaining() ) {
        byte b = bb.get( i );
        i++;
        if ( ( b & 0x80 ) == 0 ) {
            // Single-byte character
            sb.append( (char) ( b & 0x7F ) );
        } else if ( ( b & 0xE0 ) == 0xC0 ) {
            // Two-byte character
            if ( !bb.hasRemaining() ) break;
            byte b2 = bb.get( i );
            i++;
            sb.append( (char) ( ( ( b & 0x1F ) << 6 ) | ( b2 & 0x3F ) ) );
        } else if ( ( b & 0xF0 ) == 0xE0 ) {
            // Three-byte character
            if ( bb.remaining() < 2 ) break;
            byte b2 = bb.get( i );
            byte b3 = bb.get( i + 1 );
            i += 2;
            sb.append( (char) ( ( ( b & 0x0F ) << 12 ) | ( ( b2 & 0x3F ) << 6 ) | ( b3 & 0x3F ) ) );
        } else if ( ( b & 0xF8 ) == 0xF0 ) {
            // Four-byte character (not used in UTF-8, but for completeness)
            if ( bb.remaining() < 3 ) break;
            byte b2 = bb.get( i );
            byte b3 = bb.get( i + 1 );
            byte b4 = bb.get( i + 2 );
            i += 3;
            int codePoint = ( ( b & 0x07 ) << 18 ) | ( ( b2 & 0x3F ) << 12 ) | ( ( b3 & 0x3F ) << 6 ) | ( b4 & 0x3F );
            sb.append( Character.toChars( codePoint ) );
        } else {
            // Invalid UTF-8 encoding
            throw new IllegalArgumentException( "Invalid UTF-8 sequence" );
        }
    }
    return i;
}

