    if (resultMap.size() < 2) {
        throw new IllegalArgumentException("ResultMap must contain at least two vertices to form a bipartite graph");
    }

    Set<V> vertexSet = new HashSet<>(resultMap.values());
    List<V> listVertex = new ArrayList<>(vertexSet);
    int midpoint = listVertex.size() / 2;

    for (int i = 0; i < midpoint; i++) {
        for (int j = midpoint; j < listVertex.size(); j++) {
            V vertex1 = listVertex.get(i);
            V vertex2 = listVertex.get(j);
            target.addEdge(vertex1, vertex2);
        }
    }
}

