Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = paramType.getActualTypeArguments();
        if (actualTypeArguments.length > 0) {
            Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
            Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType, genericType);
            for (int i = 0; i < actualTypeArguments.length; i++) {
                Type arg = actualTypeArguments[i];
                if (arg instanceof TypeVariable) {
                    TypeVariable<?> typeVariable = (TypeVariable<?>) arg;
                    Type resolvedType = typeVariableMap.get(typeVariable);
                    if (resolvedType != null) {
                        resolvedArguments[i] = resolveRawClass(resolvedType, targetType);
                    } else {
                        return null; // Cannot resolve type variable
                    }
                } else {
                    resolvedArguments[i] = resolveRawClass(arg, targetType);
                }
            }
            return resolvedArguments;
        }
    }
    return null; // Not parameterized or cannot resolve arguments
}

Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType, Type genericType) {
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    buildTypeVariableMap(targetType, genericType, typeVariableMap);
    return typeVariableMap;
}

void buildTypeVariableMap(Class<?> targetType, Type genericType, Map<TypeVariable<?>, Type> typeVariableMap) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Type[] typeParameters = ((Class<?>) parameterizedType.getRawType()).getTypeParameters();
        for (int i = 0; i < typeParameters.length; i++) {
            typeVariableMap.put((TypeVariable<?>) typeParameters[i], actualTypeArguments[i]);
        }
        Type ownerType = parameterizedType.getOwnerType();
        if (ownerType != null) {
            buildTypeVariableMap(targetType.getEnclosingClass(), ownerType, typeVariableMap);
        }
    }
    Type superClass = targetType.getGenericSuperclass();
    if (superClass != null) {
        buildTypeVariableMap(targetType.getSuperclass(), superClass, typeVariableMap);
    }
    for (Type interfaceType : targetType.getGenericInterfaces()) {
        buildTypeVariableMap((Class<?>) ((ParameterizedType) interfaceType).getRawType(), interfaceType, typeVariableMap);
    }
}

Class<?> resolveRawClass(Type type, Class<?> context) {
    if (type instanceof Class) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    } else if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        Type[] bounds = typeVariable.getBounds();
        if (bounds.length > 0) {
            return resolveRawClass(bounds[0], context);
        }
    }
    return null; // Unknown type
}

