long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    // Extract year, month, and day from the timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the start of the month
    int daysInMonth[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
        daysInMonth[1] = 29; // Leap year
    }

    int startDayOfMonth = 1;
    int endDayOfMonth = daysInMonth[month - 1];

    // Find the closest day that is a multiple of dayStep or the last day of the month
    int compressedDay = startDayOfMonth + ((day - startDayOfMonth) / dayStep) * dayStep;
    if (compressedDay + dayStep > endDayOfMonth) {
        compressedDay = endDayOfMonth;
    }

    // Reformat the timeBucket with the compressed day
    return (year * 10000L) + (month * 100L) + compressedDay;
}

int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be valid");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        final char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // surrogate pair
                i++; // skip the low surrogate
            } else {
                size += 3; // malformed surrogate pair, treat as single unpaired high surrogate
            }
        } else {
            size += 3;
        }
    }
    return size;
}

