void pop(final String descriptor) {
    try {
        if (descriptor == null || descriptor.isEmpty()) {
            throw new IllegalArgumentException("Descriptor cannot be null or empty");
        }

        if (descriptor.startsWith("(")) {
            // It's a method descriptor, extract argument types
            int endOfArguments = descriptor.indexOf(')');
            if (endOfArguments == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String argumentsDescriptor = descriptor.substring(1, endOfArguments);
            int currentPos = 0;
            while (currentPos < argumentsDescriptor.length()) {
                char typeChar = argumentsDescriptor.charAt(currentPos);
                switch (typeChar) {
                    case 'B':
                    case 'C':
                    case 'F':
                    case 'I':
                    case 'S':
                    case 'Z':
                    case 'L': // Reference type
                    case '[': // Array type
                        currentPos = getNextTypeDescriptorEnd(argumentsDescriptor, currentPos);
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown type character in descriptor: " + typeChar);
                }
            }
        } else {
            // It's a type descriptor, pop one type
            getNextTypeDescriptorEnd(descriptor, 0);
        }
    } catch (Exception e) {
        // Handle exceptions, e.g., log or throw a specific exception
        throw new RuntimeException("Error popping from stack based on descriptor", e);
    }
}

private int getNextTypeDescriptorEnd(String descriptor, int startPos) {
    char typeChar = descriptor.charAt(startPos);
    switch (typeChar) {
        case 'B': // byte
        case 'C': // char
        case 'F': // float
        case 'I': // int
        case 'S': // short
        case 'Z': // boolean
            return startPos + 1;
        case 'D': // double
        case 'J': // long
            return startPos + 1;
        case 'L': // Reference type
            int endSemicolon = descriptor.indexOf(';', startPos);
            if (endSemicolon == -1) {
                throw new IllegalArgumentException("Invalid reference type descriptor: missing ';'");
            }
            return endSemicolon + 1;
        case '[': // Array type
            return getNextTypeDescriptorEnd(descriptor, startPos + 1);
        default:
            throw new IllegalArgumentException("Unknown type character in descriptor: " + typeChar);
    }
}

