protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0);
    }

    V startVertex = null;
    Map<V, V> vertexPredecessors = new HashMap<>();
    Map<V, Double> vertexWeights = new HashMap<>();

    for (E edge : tour) {
        if (startVertex == null) {
            startVertex = graph.getEdgeSource(edge);
        }
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexPredecessors.put(target, source);
        vertexWeights.put(target, graph.getEdgeWeight(edge));
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Tour is empty or not forming a valid path");
    }

    List<E> edgeList = new ArrayList<>();
    V currentVertex = startVertex;
    double pathWeight = 0.0;

    do {
        V nextVertex = vertexPredecessors.get(currentVertex);
        if (nextVertex == null) {
            break;
        }
        E edge = graph.getEdge(nextVertex, currentVertex);
        edgeList.add(edge);
        pathWeight += graph.getEdgeWeight(edge);
        currentVertex = nextVertex;
    } while (currentVertex != startVertex);

    if (edgeList.size() != tour.size()) {
        throw new IllegalArgumentException("Tour edges do not form a valid cycle");
    }

    return new GraphPathImpl<>(graph, startVertex, edgeList, pathWeight);
}

