private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.size() < 2) {
        return true; // A single vertex or empty set is trivially a clique
    }

    for (V vertex1 : vertices) {
        if (!graph.containsVertex(vertex1)) {
            return false; // If a vertex is not in the graph, it can't form a clique
        }
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                return false; // If there's no edge between two vertices, it's not a clique
            }
        }
    }
    return true;
}

