void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }
    try {
        if (descriptor.charAt(0) == '(') { // Method descriptor
            int i = 1;
            while (descriptor.charAt(i) != ')') {
                i = popTypeFromDescriptor(descriptor, i);
            }
        } else { // Field descriptor
            popTypeFromDescriptor(descriptor, 0);
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private int popTypeFromDescriptor(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
        case 'F':
        case 'D':
            // Single-width types
            return index + 1;
        case 'J':
            // Double-width types
            return index + 1;
        case 'L':
            // Object types
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            return index + 1;
        case '[':
            // Array types
            return popTypeFromDescriptor(descriptor, index + 1);
        default:
            throw new IllegalArgumentException("Invalid type descriptor: " + descriptor.charAt(index));
    }
}

