public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    // Normalize the input path by ensuring it ends with a slash
    String normalizedPath = path.endsWith("/") ? path : path + "/";

    // Split the relative path into segments
    String[] segments = relativePath.split("/");

    // Use a StringBuilder to construct the final path
    StringBuilder finalPath = new StringBuilder(normalizedPath);

    for (String segment : segments) {
        if (segment.equals("..")) {
            // Move up one directory if possible
            int lastSlashIndex = finalPath.lastIndexOf("/");
            if (lastSlashIndex != -1 && lastSlashIndex != 0) {
                finalPath.setLength(lastSlashIndex);
            }
        } else if (!segment.equals(".")) {
            // Append the segment if it's not the current directory
            finalPath.append(segment).append("/");
        }
    }

    // Remove the trailing slash if the original path didn't end with one
    if (!path.endsWith("/") && finalPath.charAt(finalPath.length() - 1) == '/') {
        finalPath.setLength(finalPath.length() - 1);
    }

    return finalPath.toString();
}

